const cmp=(id,title,kind,cases)=>({id,title,kind,type:'compare',cases});
export const renalLedger={filtered:[100,10,20,8],returned:[90,10,15,0],remaining:[10,0,5,8]};
export const freshRenalLedger={filtered:[120,12,18,6],returned:[105,12,13,0],remaining:[15,0,5,6]};
